const brief180={explore:['CONOCE CADA PIEZA','Explora la flota','Del exterior al último componente. Elige un tren, gira el modelo y descubre su construcción.','Entrar al taller'],maintenance:['TU PRÓXIMA INTERVENCIÓN','Resuelve la falla','Busca tus herramientas, trabaja sobre el tren y comprueba cada reparación.','Comenzar una misión'],operator:['TU LUGAR ES LA CABINA','Toma los mandos','Controla la tracción, prepara la parada y lleva a tus pasajeros hasta la siguiente estación.','Entrar en cabina'],automatic:['LA CIUDAD EN MOVIMIENTO','Recorre la red','Sigue un convoy o recorre el andén a pie para observar la operación desde otra perspectiva.','Observar la red'],substations:['DE LA ENERGÍA AL MOVIMIENTO','Entra a la subestación','Recorre los equipos, abre sus gabinetes y completa una intervención guiada por su lista de trabajo.','Explorar subestaciones']};
brief180.library=['CONSULTA Y APRENDE','Biblioteca','Consulta el portal técnico integrado, el HTML original, los cálculos y las fuentes del proyecto.','Abrir Biblioteca'];
brief180.settings=['PREPARA TU EXPERIENCIA','Ajustes','Configura los controles visuales, la exposición y los instrumentos en pantalla.','Abrir Ajustes'];
export function mountHome180(doc=document){const home=doc.getElementById('game-home'),buttons=[...doc.querySelectorAll('[data-game-mode]')];if(!home||buttons.length!==5||doc.getElementById('home180'))return false;const root=doc.createElement('div');root.id='home180';root.innerHTML='<header><a href="#game-home-title" aria-label="Metro en la ciudad, inicio"><span>M</span><strong>METRO<small>EN LA CIUDAD</small></strong></a><p>EXPERIENCIA FERROVIARIA <b>01 / 08</b></p></header><div class="home180-layout"><section class="home180-select"><small>ELIGE TU PRÓXIMO TURNO</small><nav id="game-home-menu" aria-label="Modos de juego"></nav><div class="home180-utils"><button type="button" data-home180-info>Biblioteca</button><button type="button" data-home180-settings>Ajustes</button></div></section><section class="home180-hero"><span data-home180-tag></span><h1 id="game-home-title" tabindex="-1">Toma los mandos</h1><p data-home180-description></p><button type="button" data-home180-start><span></span><b aria-hidden="true">→</b></button><div class="home180-lines"><span><b>1</b> NM-22</span><span><b>8</b> NM-79 · MP-82</span></div></section></div><footer><span>EXPLORA. COMPRENDE. OPERA.</span><span>↑ ↓ Elegir modo · Entrar para comenzar</span></footer>';
 const old=[...home.children];home.append(root);let selected='operator';const nav=root.querySelector('nav');const library=root.querySelector('[data-home180-info]'),settings=root.querySelector('[data-home180-settings]');library.dataset.homeEntry200='library';settings.dataset.homeEntry200='settings';library.innerHTML='<span class="game-menu-number">06</span><span><b>Biblioteca</b><small>Portal técnico, HTML original y fuentes.</small></span>';settings.innerHTML='<span class="game-menu-number">07</span><span><b>Ajustes</b><small>Personaliza la imagen y los instrumentos.</small></span>';const entries=[...buttons,library,settings],entryId=b=>b.dataset.gameMode||b.dataset.homeEntry200;const preview=id=>{selected=id;const [tag,title,text,action]=brief180[id];root.dataset.mode=id;root.querySelector('[data-home180-tag]').textContent=tag;root.querySelector('#game-home-title').textContent=title;root.querySelector('[data-home180-description]').textContent=text;root.querySelector('[data-home180-start]').querySelector('span').textContent=action;for(const b of entries)b.setAttribute('data-selected180',String(entryId(b)===id));};for(const b of entries){nav.append(b);b.addEventListener('pointerenter',()=>preview(entryId(b)));b.addEventListener('focus',()=>preview(entryId(b)));}for(const n of old)n.remove();root.querySelector('[data-home180-start]').onclick=()=>entries.find(b=>entryId(b)===selected).click();root.querySelector('[data-home180-info]').onclick=()=>doc.getElementById('documents-open').click();root.querySelector('[data-home180-settings]').onclick=()=>globalThis.window?.metroGameShell105?.openSettings();root.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','Enter'].includes(e.key)||e.target.tagName==='BUTTON'&&e.key==='Enter')return;e.preventDefault();const i=entries.findIndex(b=>entryId(b)===selected);if(e.key==='Enter')entries[i].click();else entries[(i+(e.key==='ArrowDown'?1:entries.length-1))%entries.length].focus();});preview(selected);return true;}
if(typeof document!=='undefined'){if(!mountHome180()){const obs=new MutationObserver(()=>{if(mountHome180())obs.disconnect();});obs.observe(document.body,{childList:true,subtree:true});}}
